using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;
namespace EanEtikety {
public class LabelIssue {public int Element=-2,Record,Page;public bool Blocking;public string Message;public override string ToString(){return (Blocking?Loc.T("Chyba"):Loc.T("Upozornenie"))+": "+(Record>0?Loc.T("Záznam")+" "+Record+", ":"")+(Page>0?Loc.T("Strana")+" "+Page+" — ":"")+Message;}}
public static class LabelChecks {
 public static List<LabelIssue> Inspect(LabelSettings s){var result=new List<LabelIssue>();Action<int,bool,string> add=(i,b,m)=>result.Add(new LabelIssue{Element=i,Blocking=b,Message=m});var codes=new List<int>();if(!s.HideBarcode){codes.Add(-1);try{if(Engine.IsGs1(s))Gs1.Payload(s.ApplicationIdentifiers);else Engine.Normalize(s.Ean,s.Kind);if(Engine.Module(s)<1)throw new Exception(Loc.T("Kód je pre zvolené rozlíšenie príliš úzky."));}catch(Exception ex){add(-1,true,ex.Message);}}
  foreach(int index in Elements.Indices(s)){ElementEdit el;try{el=ElementTransform.Get(s,index);}catch{continue;}if(ElementTransform.Outside(s,el))add(index,false,Loc.T("Prvok presahuje etiketu"));if(index<=-3){var symbol=s.Symbols[-3-index];try{if(symbol.Code!=null){codes.Add(index);Engine.Validate(symbol.Code.Settings());}if(symbol.Matrix!=null){codes.Add(index);var matrix=Assets.Matrix(symbol.Matrix);if(symbol.Width*s.Dpi/25.4<matrix.Width||Math.Abs(symbol.Width-symbol.Height)>.01)throw new Exception(Loc.T("Neplatné rozmery 2D kódu"));}if(symbol.Image!=null){Assets.Validate(symbol.Image);if(symbol.Image.Mime!="image/svg+xml"&&Math.Min(symbol.Image.PixelWidth*symbol.Image.CropWidth/symbol.Width,symbol.Image.PixelHeight*symbol.Image.CropHeight/symbol.Height)*25.4<s.Dpi*.75)add(index,false,Loc.T("Nízke rozlíšenie obrázka pri tlači"));}}catch(Exception ex){add(index,true,ex.Message);}}
   if(index>=0){var t=s.Texts[index];using(var b=new Bitmap(1,1))using(var g=Graphics.FromImage(b))using(var family=VectorArt.Family(t.FontName))using(var font=new Font(family,(float)(t.Size*s.Dpi/72),VectorArt.Style(family,t.Bold),GraphicsUnit.Pixel))using(var format=new StringFormat(StringFormat.GenericTypographic)){var size=g.MeasureString(t.Text,font,new SizeF((float)(t.Width*s.Dpi/25.4),100000),format);if(size.Height>t.Height*s.Dpi/25.4+1)add(index,false,Loc.T("Text sa nezmestí do poľa"));}}
  }
  foreach(int code in codes){ElementEdit e;try{e=ElementTransform.Get(s,code);}catch{continue;}double left=.08*e.Width,right=left,vertical=0;try{if(code<=-3&&s.Symbols[-3-code].Matrix!=null){var content=s.Symbols[-3-code].Matrix;var matrix=Assets.Matrix(content);double step=Math.Floor(e.Width/matrix.Width*s.Dpi/25.4)*25.4/s.Dpi;left=right=vertical=(e.Width-step*matrix.Width)/2+(content.Type=="QR"?4:1)*step;}else{var data=code==-1?s:s.Symbols[-3-code].Code.Settings();double scale=e.Width/data.BarWidth,step=Engine.Module(data)*25.4/data.Dpi*scale,padding=(e.Width-Engine.Modules(data)*step)/2;left=padding+Engine.Quiet(data.Kind)*step;right=padding+(data.Kind==13?7:Engine.Quiet(data.Kind))*step;}}catch{continue;}var strips=new List<RectangleF>{new RectangleF((float)e.X,(float)e.Y,(float)left,(float)e.Height),new RectangleF((float)(e.X+e.Width-right),(float)e.Y,(float)right,(float)e.Height)};if(vertical>0){strips.Add(new RectangleF((float)e.X,(float)e.Y,(float)e.Width,(float)vertical));strips.Add(new RectangleF((float)e.X,(float)(e.Y+e.Height-vertical),(float)e.Width,(float)vertical));}foreach(int other in Elements.Indices(s)){if(other==code)continue;try{using(var objectPath=new GraphicsPath()){objectPath.AddPolygon(ElementTransform.Corners(ElementTransform.Get(s,other)));foreach(var strip in strips)using(var quietPath=new GraphicsPath()){quietPath.AddRectangle(strip);using(var m=ElementTransform.Matrix(e.Rotation,ElementTransform.Center(e)))quietPath.Transform(m);using(var region=new Region(quietPath)){region.Intersect(objectPath);using(var identity=new Matrix())if(region.GetRegionScans(identity).Length>0){add(other,false,Loc.T("Prvok zasahuje do voľného priestoru kódu"));break;}}}}}catch(ArgumentException){}}
  }if(Elements.Indices(s).Count==0)add(-2,true,Loc.T("Dokument neobsahuje nič na tlač."));try{Engine.Validate(s);}catch(Exception ex){if(!result.Exists(i=>i.Message==ex.Message))add(-2,true,ex.Message);}return result;
 }
}

}
